#include <stdio.h>

/* 用指针把 a 中从第 start 个（1 基）开始的 n 个数逆序 */
void reverse(int *a, int start, int n)
{
    int *p = a + start - 1;
    int *q = p + n - 1;
    int t;

    while (p < q) {
        t = *p;
        *p = *q;
        *q = t;
        p = p + 1;
        q = q - 1;
    }
}

